  int32_t h = snapshot->header.h;

  fprintf(fp, "P6\n%d %d\n255\n", w, h);

  /* Convert ARGB8888 → RGB888 */
  uint32_t *argb = (uint32_t *)snapshot->data;
  for (int32_t y = 0; y < h; y++)
    {
      for (int32_t x = 0; x < w; x++)
        {
          uint32_t px = argb[y * w + x];
          uint8_t r = (px >> 16) & 0xFF;
          uint8_t g = (px >> 8)  & 0xFF;
          uint8_t b =  px        & 0xFF;
          fputc(r, fp);
          fputc(g, fp);
          fputc(b, fp);
        }
    }

  fclose(fp);
  printf("Screenshot saved: %s (%dx%d)\n", out_path, w, h);

  /* Cleanup */
  lv_draw_buf_destroy(snapshot);
  free(buf);
  lv_deinit();

  return 0;
}

