/* ================================================================
 * MAIN ENTRY
 * ================================================================ */

int main(int argc, char **argv)
{
    configure_simulator(argc, argv);

    lv_init();

    driver_backends_register();

    if (driver_backends_init_backend(selected_backend) == -1)
        die("Failed to initialize display backend");

    if (settings.rotation)
        lv_display_set_rotation(NULL, settings.rotation);

    create_deskmate_screen();

#if LV_USE_EVDEV
    if (driver_backends_init_backend("EVDEV") == -1)
        LV_LOG_WARN("Failed to initialize evdev (keyboard may not work)");
#endif

    driver_backends_run_loop();
    return 0;
}

/* ================================================================
 * UTILITY FUNCTIONS
 * ================================================================ */

static void print_lvgl_version(void)
{
    printf("LVGL version: %d.%d.%d\n",
           lv_version_major(), lv_version_minor(), lv_version_patch());
    printf("Backend backends: ");
    driver_backends_print_supported();
}

static void print_usage(void)
{
    printf("Usage: lvglsim [options]\n");
    printf("Options:\n");
    printf("  -b <backend>   Backend to use (SDL, WAYLAND, X11, DRM, FBDEV, GLFW)\n");
    printf("  -W <width>     Window width (default: 800)\n");
    printf("  -H <height>    Window height (default: 480)\n");
    printf("  -R <rotation>  Display rotation (0, 90, 180, 270)\n");
    printf("  -f             Fullscreen\n");
    printf("  -B             List supported backends\n");
    printf("  -V             Print version\n");
    printf("  -h             Print this help\n");
    printf("\nExamples:\n");
    printf("  lvglsim -W 1920 -H 1200 -b SDL\n");
}

static void configure_simulator(int argc, char **argv)
{
    int opt;
    const char *backend = "SDL";
    int width = 800, height = 480;
    int rotation = 0;
    int fullscreen = 0;

    if (argc == 1)
        return;

    while ((opt = getopt(argc, argv, "b:W:H:R:fBVh")) != -1) {
        switch (opt) {
        case 'b':
            backend = optarg;
            break;
        case 'W':
            width = atoi(optarg);
            break;
        case 'H':
            height = atoi(optarg);
            break;
        case 'R':
            rotation = atoi(optarg);
            break;
        case 'f':
            fullscreen = 1;
            break;
        case 'B':
            driver_backends_print_supported();
            exit(0);
        case 'V':
            print_lvgl_version();
            exit(0);
        case 'h':
        default:
            print_usage();
            exit(0);
        }
    }

    selected_backend = strdup(backend);
    settings.window_width = width;
    settings.window_height = height;
    settings.rotation = rotation;
    settings.fullscreen = fullscreen;
    settings.maximize = false;
}

