 * CLOCK UPDATE CALLBACK
 * ================================================================ */

static void clock_update_cb(lv_timer_t *timer)
{
    (void)timer;
    time_t now;
    struct tm tm;
    time(&now);
    localtime_r(&now, &tm);

    char buf[32];

    /* Time HH:MM */
    snprintf(buf, sizeof(buf), "%02d:%02d", tm.tm_hour, tm.tm_min);
    lv_label_set_text(clock_label, buf);
    if (clock_big_label)
        lv_label_set_text(clock_big_label, buf);
    if (standby_clock_label)
        lv_label_set_text(standby_clock_label, buf);

    /* Date: Thu  Jul 24 */
    static const char *en_weekdays[] =
        { "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat" };
    static const char *en_months[] =
        { "Jan", "Feb", "Mar", "Apr", "May", "Jun",
          "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };
    snprintf(buf, sizeof(buf), "%s  %s %d",
             en_weekdays[tm.tm_wday],
             en_months[tm.tm_mon],
             tm.tm_mday);
    if (clock_date_label)
        lv_label_set_text(clock_date_label, buf);
    if (standby_date_label)
        lv_label_set_text(standby_date_label, buf);
}

